({
  // --- Model Helpers ---

  _ensureInit() {
    if (!this.data || typeof this.data !== "object") {
      this.data = {};
    }
    if (!this.data.topics || typeof this.data.topics !== "object") {
      this.data.topics = {};
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === "object", "this.data must be an object");
    this.invariant(this.data.topics && typeof this.data.topics === "object", "this.data.topics must be an object");

    for (const [topic, subscribers] of Object.entries(this.data.topics)) {
      this.invariant(typeof topic === "string" && topic.length > 0, "Topic keys must be non-empty strings");
      this.invariant(Array.isArray(subscribers), `Subscriber list for topic '${topic}' must be an array`);

      const uniqueSet = new Set(subscribers);
      this.invariant(uniqueSet.size === subscribers.length, `Topic '${topic}' must not contain duplicate subscribers`);

      for (const id of subscribers) {
        this.invariant(typeof id === "string" && id.length > 0, "Subscriber ID must be a non-empty string");
      }
    }
  },

  _addSubscriber(topic, subscriberId) {
    if (!this.data.topics[topic]) {
      this.data.topics[topic] = [];
    }
    if (!this.data.topics[topic].includes(subscriberId)) {
      this.data.topics[topic].push(subscriberId);
      return true;
    }
    return false;
  },

  _removeSubscriber(topic, subscriberId) {
    if (!this.data.topics[topic]) {
      return false;
    }
    const idx = this.data.topics[topic].indexOf(subscriberId);
    if (idx !== -1) {
      this.data.topics[topic].splice(idx, 1);
      if (this.data.topics[topic].length === 0) {
        delete this.data.topics[topic];
      }
      return true;
    }
    return false;
  },

  _getSubscribers(topic) {
    if (!this.data.topics || !this.data.topics[topic]) {
      return [];
    }
    return [...this.data.topics[topic]];
  },

  // --- Public Handlers ---

  async subscribe(msg) {
    this._ensureInit();
    this.ensure(msg && typeof msg === "object", "Message must be an object");
    this.ensure(msg.payload && typeof msg.payload === "object", "Message payload must be an object");

    const { topic, subscriberId } = msg.payload;
    this.ensure(typeof topic === "string" && topic.trim().length > 0, "Topic must be a non-empty string");
    this.ensure(typeof subscriberId === "string" && subscriberId.trim().length > 0, "Subscriber ID must be a non-empty string");

    const normalizedTopic = topic.trim();
    const normalizedSubscriberId = subscriberId.trim();

    const added = this._addSubscriber(normalizedTopic, normalizedSubscriberId);
    this._checkInvariants();

    this.changed("subscription", {
      topic: normalizedTopic,
      subscriberId: normalizedSubscriberId,
      action: "subscribed",
      isNew: added
    });

    const subscribers = this._getSubscribers(normalizedTopic);
    this.ensure(subscribers.includes(normalizedSubscriberId), "Subscriber must be present in topic subscribers list after subscribe");

    return {
      success: true,
      topic: normalizedTopic,
      subscriberId: normalizedSubscriberId,
      isNew: added,
      subscriberCount: subscribers.length
    };
  },

  async unsubscribe(msg) {
    this._ensureInit();
    this.ensure(msg && typeof msg === "object", "Message must be an object");
    this.ensure(msg.payload && typeof msg.payload === "object", "Message payload must be an object");

    const { topic, subscriberId } = msg.payload;
    this.ensure(typeof topic === "string" && topic.trim().length > 0, "Topic must be a non-empty string");
    this.ensure(typeof subscriberId === "string" && subscriberId.trim().length > 0, "Subscriber ID must be a non-empty string");

    const normalizedTopic = topic.trim();
    const normalizedSubscriberId = subscriberId.trim();

    const removed = this._removeSubscriber(normalizedTopic, normalizedSubscriberId);
    this._checkInvariants();

    this.changed("subscription", {
      topic: normalizedTopic,
      subscriberId: normalizedSubscriberId,
      action: "unsubscribed",
      wasPresent: removed
    });

    const subscribers = this._getSubscribers(normalizedTopic);
    this.ensure(!subscribers.includes(normalizedSubscriberId), "Subscriber must not be present in topic subscribers list after unsubscribe");

    return {
      success: true,
      topic: normalizedTopic,
      subscriberId: normalizedSubscriberId,
      removed,
      subscriberCount: subscribers.length
    };
  },

  async getSubscribers(msg) {
    this._ensureInit();
    this.ensure(msg && typeof msg === "object", "Message must be an object");
    this.ensure(msg.payload && typeof msg.payload === "object", "Message payload must be an object");

    const { topic } = msg.payload;
    this.ensure(typeof topic === "string" && topic.trim().length > 0, "Topic must be a non-empty string");

    const normalizedTopic = topic.trim();
    const subscribers = this._getSubscribers(normalizedTopic);

    this.ensure(Array.isArray(subscribers), "Subscribers result must be an array");

    return {
      topic: normalizedTopic,
      subscribers,
      count: subscribers.length
    };
  },

  async publish(msg) {
    this._ensureInit();
    this.ensure(msg && typeof msg === "object", "Message must be an object");
    this.ensure(msg.payload && typeof msg.payload === "object", "Message payload must be an object");

    const { topic, message } = msg.payload;
    this.ensure(typeof topic === "string" && topic.trim().length > 0, "Topic must be a non-empty string");
    this.ensure(message !== undefined, "Message must be provided");

    const normalizedTopic = topic.trim();
    const subscribers = this._getSubscribers(normalizedTopic);

    const deliveries = [];
    for (const subscriberId of subscribers) {
      try {
        const response = await this.call(subscriberId, "notify", {
          topic: normalizedTopic,
          message
        });
        deliveries.push({
          subscriberId,
          success: true,
          response
        });
      } catch (error) {
        deliveries.push({
          subscriberId,
          success: false,
          error: error?.message || String(error)
        });
      }
    }

    this.changed("publication", {
      topic: normalizedTopic,
      message,
      deliveredTo: deliveries.length
    });

    this.ensure(deliveries.length === subscribers.length, "All registered subscribers must be processed for delivery");

    return {
      topic: normalizedTopic,
      subscriberCount: subscribers.length,
      deliveries
    };
  }
})
